import React, {useState} from 'react';
import {
  View,
  Modal,
  Pressable,
  Text,
  KeyboardAvoidingView,
  Platform,
  TouchableWithoutFeedback,
  Keyboard,
} from 'react-native';
import {Input, Icon, Button} from '@ui-kitten/components';
import TextCM from '../Text';
import ButtonCM from '../Button';
import styles from './styles';

type ModalInputFormProps = {
  visible: boolean;
  onClose: () => void;
  title: string;
  fields: {
    label: string;
    placeholder: string;
    value: string;
    onChange: (text: string) => void;
    required?: boolean;
    multiline?: boolean;
    maxLength?: number;
  }[];
  onSubmit: () => void;
  isSubmitting?: boolean;
  submitLabel?: string;
  cancelLabel?: string;
};

const ModalInputForm = ({
  visible,
  onClose,
  title,
  fields,
  onSubmit,
  isSubmitting = false,
  submitLabel = 'Lưu',
  cancelLabel = 'Hủy',
}: ModalInputFormProps) => {
  const [errors, setErrors] = useState<boolean[]>(fields.map(() => false));

  const isFormValid = fields.every(
    (field, index) => !field.required || (field.value.trim() && !errors[index]),
  );

  const handleInputChange = (
    index: number,
    text: string,
    required?: boolean,
  ) => {
    fields[index].onChange(text);
    if (required) {
      setErrors(prev => {
        const newErrors = [...prev];
        newErrors[index] = !text.trim();
        return newErrors;
      });
    }
  };

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={onClose}>
      <TouchableWithoutFeedback onPress={Keyboard.dismiss}>
        <View style={styles.modal}>
          <KeyboardAvoidingView
            behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
            style={styles.keyctn}>
            <View style={styles.modelEdit}>
              {/* Header */}
              <View style={styles.modelHeader}>
                <TextCM style={styles.textHeaderEdit}>{title}</TextCM>
              </View>

              {/* Các trường nhập liệu */}
              {fields.map((field, index) => (
                <View key={index} style={{marginBottom: 12}}>
                  <TextCM style={{marginBottom: 4}}>
                    {field.label}{' '}
                    {field.required && (
                      <TextCM style={{color: 'red'}}>*</TextCM>
                    )}
                  </TextCM>
                  <Input
                    placeholder={field.placeholder}
                    value={field.value}
                    onChangeText={text =>
                      handleInputChange(index, text, field.required)
                    }
                    status={errors[index] ? 'danger' : 'basic'}
                    multiline={field.multiline}
                    maxLength={field.maxLength}
                    textStyle={
                      field.multiline ? styles.textDescription : undefined
                    }
                    style={{marginBottom: errors[index] ? 2 : 12}}
                  />
                  {errors[index] && (
                    <TextCM style={{color: 'red', marginTop: 4}}>
                      Không được để trống thông tin
                    </TextCM>
                  )}
                  {field.maxLength && (
                    <TextCM style={{textAlign: 'right', marginTop: 4}}>
                      {field.value.length}/{field.maxLength}
                    </TextCM>
                  )}
                </View>
              ))}

              {/* Nút hành động */}
              <View style={styles.bottomEdit}>
                <Button status="basic" onPress={onClose}>
                  {cancelLabel}
                </Button>
                <ButtonCM
                  disabled={!isFormValid}
                  onPress={onSubmit}
                  style={{backgroundColor: '#CA1E66', borderWidth: 0}}
                  label={submitLabel}
                  loading={isSubmitting}
                />
              </View>
            </View>
          </KeyboardAvoidingView>
        </View>
      </TouchableWithoutFeedback>
    </Modal>
  );
};

export default ModalInputForm;
