import {Pressable, View} from 'react-native'; // 👈 thêm Modal
import InitialAvatar from './InitialAvatar';
import {Color} from '../../../../constants';
import styles from '../styles';
import {WorkSpace} from '../../../../model/interface/home.interface';
import TextCM from '../../../components/Text';
import {Icon, Layout, Popover, ProgressBar} from '@ui-kitten/components';
import {useState} from 'react';
import {useHomeService} from '../../../../hooks/useHomeService';
import Toast from 'react-native-toast-message';
import ModalInputForm from '../../../components/ModalInputForm';
import ModalConfirmCM from '../../../components/ModalConfirm';
import {useTranslation} from 'react-i18next';

type CardProps = {
  data: WorkSpace;
  backgroundColor?: keyof typeof Color;
  onPress?: () => void;
  onDeleteSuccess?: (deletedId: string) => void;
  onEditSuccess?: (updated: WorkSpace) => void;
};

const Card = ({
  data,
  backgroundColor,
  onPress,
  onDeleteSuccess,
  onEditSuccess,
}: CardProps) => {
  const {t} = useTranslation();
  const [visible, setVisible] = useState(false);

  const [confirmDeleteVisible, setConfirmDeleteVisible] = useState(false);
  const [confirmEdit, setConfirmEdit] = useState(false);
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [errorName, setErrorName] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const HomeService = useHomeService();
  const progress = data.totalTask
    ? data.totalTaskCompleted / data.totalTask
    : 0;

  const handleConfirmDelete = async () => {
    try {
      const res = await HomeService.deleteWorkSpaceById(data?.id);

      if (res) {
        setConfirmDeleteVisible(false);
        onDeleteSuccess?.(data.id);
        Toast.show({
          type: 'success',
          text1: t('CM.noti'),
          text2: t('task.delete-space-success'),
        });
      } else {
      }
    } catch (error) {}
  };
  const handleSave = async () => {
    if (!name.trim()) {
      setErrorName(true);
      return;
    }
    setErrorName(false);
    setIsSaving(true);
    try {
      const payload = {
        ...data,
        name: name.trim(),
        description: description.trim(),
      };
      const res = await HomeService.updateWorkSpace(payload);

      if (res && res.data) {
        setConfirmEdit(false);
        onEditSuccess?.(res.data);
        setIsSaving(false);
        Toast.show({
          type: 'success',
          text1: t('CM.noti'),
          text2: t('task.edit-space-success'),
        });
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('board.edit-space-not-success'),
        });
      }
    } catch (error) {
      console.log('error', error);
    } finally {
      setIsSaving(false);
    }
  };

  const renderDelete = () => (
    <View style={{flexDirection: 'row', alignItems: 'center', gap: 4}}>
      <Icon name="trash-outline" style={styles.icon} />
      <TextCM style={styles.optionText}>{t('CM.delete')}</TextCM>
    </View>
  );

  const renderEdit = () => (
    <View style={styles.headerFirst}>
      <Icon name="edit-outline" style={styles.icon} />
      <TextCM style={styles.optionText}>{t('CM.edit')}</TextCM>
    </View>
  );

  return (
    <View
      style={[
        styles.cardContainer,
        {backgroundColor: Color[backgroundColor || 'pending']},
      ]}>
      <Pressable onPress={onPress} style={{flex: 1}}>
        <View style={styles.cardFirst}>
          <InitialAvatar text={data.name} />
          <View style={styles.textFirst}>
            <View style={styles.headerFirst}>
              <TextCM style={styles.textBold} numberOfLines={1}>
                {data.name}
              </TextCM>
              <Popover
                visible={visible}
                anchor={() => (
                  <Pressable onPress={() => setVisible(true)}>
                    <Icon
                      name="more-horizontal-outline"
                      style={styles.iconMore}
                    />
                  </Pressable>
                )}
                placement="bottom end"
                onBackdropPress={() => setVisible(false)}>
                <Layout style={styles.popoverContent}>
                  <Pressable
                    onPress={() => {
                      setVisible(false);
                      setName(data.name);
                      setDescription(data.description);
                      setConfirmEdit(true);
                    }}>
                    {renderEdit()}
                  </Pressable>
                  <Pressable
                    onPress={() => {
                      setVisible(false);
                      setConfirmDeleteVisible(true);
                    }}>
                    {renderDelete()}
                  </Pressable>
                </Layout>
              </Popover>
            </View>
            <TextCM style={styles.colorText} numberOfLines={2}>
              {data.description}
            </TextCM>
          </View>
        </View>

        <View style={{padding: 10}}>
          <TextCM style={styles.textCenter}>
            {t('board.implement-progress')}
          </TextCM>
          <View style={styles.progressRow}>
            <ProgressBar
              progress={progress}
              status="control"
              style={{flex: 1}}
            />
            <TextCM style={styles.progressText}>
              {(progress * 100).toFixed(2)}%
            </TextCM>
            <TextCM style={styles.progressCount}>
              ({data.totalTaskCompleted}/{data.totalTask})
            </TextCM>
          </View>
        </View>

        <View style={styles.creatorSection}>
          <View style={styles.avatar}>
            <TextCM style={styles.avatarText}>
              {data.owner.charAt(0).toUpperCase()}
            </TextCM>
          </View>
          <TextCM style={styles.creatorText}>
            {t('board.creat-by')} {data.owner}
          </TextCM>
        </View>
      </Pressable>

      <ModalConfirmCM
        type="cancel"
        isVisible={confirmDeleteVisible}
        onClose={() => setConfirmDeleteVisible(false)}
        content={t('board.delete-space-confirm')}
        title={`${t('board.delete-space')} "${data.name}"?`}
        onConfirm={handleConfirmDelete}
        styleBtnRight={{backgroundColor: Color.RedE14337}}
        labelCancel={t('CM.labelCancel')}
        labelConfirm={t('CM.confirm')}
      />
      <ModalInputForm
        visible={confirmEdit}
        onClose={() => {
          setConfirmEdit(false);
          setName('');
          setDescription('');
          setErrorName(false);
        }}
        title={t('board.edit-space')}
        fields={[
          {
            label: t('board.space-name'),
            placeholder: t('board.space-name-placeholder'),
            value: name,
            onChange: text => {
              setName(text);
              setErrorName(!text.trim());
            },
            required: true,
          },
          {
            label: t('board.introduce'),
            placeholder: t('NT.board.placeholderDescription'),
            value: description,
            onChange: setDescription,
            multiline: true,
            maxLength: 225,
          },
        ]}
        onSubmit={handleSave}
        isSubmitting={isSaving}
        submitLabel={t('CM.save')}
        cancelLabel={t('CM.labelCancel')}
      />
    </View>
  );
};

export default Card;
