import {
  CalendarRange,
  Divider,
  Icon,
  IndexPath,
  RangeDatepicker,
} from '@ui-kitten/components';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {Pressable, ScrollView, View} from 'react-native';
import InputCM from '../../../../../../components/TextField/InputCM';
import DropdownListCM from '../../../../../../components/DropDownList';
import {PRIORITIES} from '../../../../../board/components/create-new-task/helper';
import {useState} from 'react';
import TextCM from '../../../../../../components/Text';
import styles from './styles';
import {AssignTaskList, AssignGroupList, AssignOrgList} from '../../helper';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import ModalSelectUser from '../../../../../../components/ModalSelectUser';
import ButtonCM from '../../../../../../components/Button';
import {isEmpty} from 'lodash';
import RenderListUserAssign from '../../../item-ticket/list-assign';
import {useTranslation} from 'react-i18next';

type Props = {
  onClose: () => void;
  resourceId?: string;
  handleSubmitData: (data: any) => void;
};

const AddTaskScreen = ({onClose, resourceId, handleSubmitData}: Props) => {
  const {t} = useTranslation();
  const [priorityIndex, setPriorityIndex] = useState<IndexPath | undefined>(
    undefined,
  );
  const [range, setRange] = useState<CalendarRange<Date>>({
    startDate: new Date(),
  });
  const [dataName, setDataName] = useState<string>('');
  const [errorName, setErrorName] = useState('');
  const [assignUserList, setAssignUserList] = useState<
    AssignTaskList[] | undefined
  >([]);
  const [assignGroupUserList, setAssignGroupUserList] = useState<
    AssignGroupList[] | undefined
  >([]);
  const [assignDepartmentsList, setAssignDepartmentsList] = useState<
    AssignOrgList[] | undefined
  >([]);
  const [openModal, setOpenModal] = useState<'assign' | 'tags' | null>(null);

  const handleChangeValue = (value: string) => {
    setDataName(value);
    if (!value) {
      setErrorName(t('task.cant-empty'));
    } else {
      setErrorName('');
    }
  };

  const handleResponseData = (data: any) => {
    setAssignUserList(data.assignUserList);
    setAssignGroupUserList(data.assignGroupUserList);
    setAssignDepartmentsList(data.assignDepartmentsList);
  };

  const handleSubmit = async () => {
    if (!dataName) {
      setErrorName(t('task.cant-empty'));
      return;
    }
    const dataUpdate = {
      name: dataName,
      startDate: range.startDate,
      endDate: range.endDate,
      priority: PRIORITIES?.[priorityIndex?.row as any]?.value || null,
      assignTaskList:
        assignUserList?.map(user =>
          user.resourceId
            ? user
            : {
                ...user,
                resourceId: resourceId,
              },
        ) || [],
      assignGroupList:
        assignGroupUserList?.map(g =>
          g.resourceId
            ? g
            : {
                ...g,
                resourceId: resourceId,
              },
        ) || [],
      assignOrgList:
        assignDepartmentsList?.map(d =>
          d.resourceId
            ? d
            : {
                ...d,
                resourceId: resourceId,
              },
        ) || [],
    };
    handleSubmitData(dataUpdate);
    onClose();
  };
  return (
    <>
      <HeaderCM
        style={{
          backgroundColor: '#fff',
        }}
        contentStyle={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#000810',
        }}
        fillIconBackLeft="#000810"
        onPressIconLeft={() => {
          onClose?.();
        }}
        title={t('task.add-work')}
        alignment="start"
      />
      <Divider />

      <ScrollView
        contentContainerStyle={{rowGap: 10}}
        style={{flex: 1, padding: 16}}>
        <InputCM
          isRequired
          label={t('HM.board.name-task')}
          placeholder={t('task.name-placeholder')}
          value={dataName}
          onChangeText={text => handleChangeValue(text)}
          captionText={errorName}
        />

        <View
          style={{
            rowGap: 10,
          }}>
          <TextCM>{t('task.assignee')}</TextCM>
          {assignUserList?.length == 0 &&
          assignGroupUserList?.length == 0 &&
          assignDepartmentsList?.length == 0 ? (
            <Pressable
              onPress={() => setOpenModal('assign')}
              style={styles.addItem}>
              <Icon name="person-add" width={16} height={16} />
            </Pressable>
          ) : (
            <Pressable onPress={() => setOpenModal('assign')}>
              <RenderListUserAssign
                assignTaskList={assignUserList}
                assignGroupList={assignGroupUserList}
                assignOrgList={assignDepartmentsList}
              />
            </Pressable>
          )}
        </View>

        <TextCM>{t('task.signDate')}</TextCM>
        <RangeDatepicker
          range={range}
          size="medium"
          controlStyle={styles.calender}
          onSelect={nextRange => setRange(nextRange)}
          min={new Date(1900, 0, 0)}
          placeholder={props => (
            <TextCM {...props}>{t('board.from-date-to-date')}</TextCM>
          )}
        />
        <DropdownListCM
          label={t('task.priority')}
          placeholder={t('task.choose-priority')}
          size="medium"
          valueSelect={priorityIndex}
          onSelect={setPriorityIndex}
          listData={PRIORITIES}
          isi18n={true}
        />
      </ScrollView>

      <View style={styles.ctnFooter}>
        <ButtonCM style={{flex: 1}} onPress={onClose} label={t('CM.back')} />
        <ButtonCM
          disabled={isEmpty(errorName) ? false : true}
          style={{flex: 1}}
          onPress={handleSubmit}
          label={t('CM.save')}
        />
      </View>

      <ModalFullScreen
        isVisible={openModal === 'assign'}
        children={
          <ModalSelectUser
            onClose={() => setOpenModal(null)}
            type="T"
            assignTaskList={assignUserList}
            assignGroupList={assignGroupUserList}
            assignOrgList={assignDepartmentsList}
            handleResponseData={handleResponseData}
          />
        }
      />
    </>
  );
};

export default AddTaskScreen;
